import json
import subprocess
import sys


def load(rev: str) -> dict:
    if rev == "WORKTREE":
        return json.load(open("package-lock.json"))["packages"]
    out = subprocess.run(["git", "show", f"{rev}:package-lock.json"], capture_output=True, text=True, check=True)
    return json.loads(out.stdout)["packages"]


before, after = load(sys.argv[1]), load(sys.argv[2])
flags = ("peer", "optional", "dev", "devOptional")
added, removed = [], []
for key in set(before) & set(after):
    for flag in flags:
        if before[key].get(flag) and not after[key].get(flag):
            removed.append((flag, key))
        if after[key].get(flag) and not before[key].get(flag):
            added.append((flag, key))
print(f"{sys.argv[1]} -> {sys.argv[2]}")
print(f"  removed {len(removed)}, added {len(added)}")
for label, items in (("-", removed), ("+", added)):
    for flag, key in sorted(items)[:6]:
        print(f"  {label}{flag}: {key}")
